#!/usr/bin/env python3
"""Audit all friend/* branch history for Friend-Message: 1 commits vs the published transcript."""
import subprocess, re, glob, sys

TALK = "/tmp/ross/talk"
MAIN = "/tmp/ross/main"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def run(args, cwd=TALK):
    return subprocess.run(args, capture_output=True, text=True, cwd=cwd).stdout


def all_messages():
    msgs = {}
    for b in BRANCHES:
        shas = run(["git", "rev-list", f"origin/friend/{b}"]).split()
        for sha in shas:
            body = run(["git", "show", sha, "--format=%B", "--no-patch"])
            if re.search(r'^Friend-Message: 1\s*$', body, re.M):
                ts = run(["git", "show", "-s", "--format=%cI", sha]).strip()
                ep = re.search(r'^Episode: (\S+)\s*$', body, re.M)
                msgs[sha] = dict(branch=b, ts=ts, ep=ep.group(1) if ep else "?")
    return msgs


def transcribed():
    t = {}
    for f in glob.glob(MAIN + "/S*/*.md"):
        text = open(f).read()
        for m in re.finditer(r'Source: friend/(\w+) @ ([0-9a-f]{40})', text):
            t[m.group(2)] = (m.group(1), f)
    return t


def main():
    msgs = all_messages()
    tr = transcribed()
    missing = {sha: v for sha, v in msgs.items() if sha not in tr}
    extra = {sha: v for sha, v in tr.items() if sha not in msgs}
    print(f"total friend messages: {len(msgs)}; transcribed: {len(tr)}; missing: {len(missing)}; unknown-in-transcript: {len(extra)}")
    for sha, v in sorted(missing.items(), key=lambda kv: kv[1]["ts"]):
        print("MISSING", v["ts"], v["ep"], "friend/" + v["branch"], sha)
    for sha, v in extra.items():
        print("UNKNOWN", sha, v)


if __name__ == "__main__":
    main()
